      { id: 1, section: "Supply Chain", question: "Définissez la chaîne d’approvisionnement (Supply Chain).", answer: "Correction : Réseau coordonné reliant fournisseurs, producteurs, entrepôts, transporteurs et distributeurs pour approvisionner, fabriquer et distribuer des produits aux clients finaux au bon moment, au bon endroit et au coût optimal." },
      { id: 4, section: "Gestion des flux", question: "Distinguez flux physique, flux d’information et flux financier.", answer: "Correction : Le flux physique est la circulation matérielle des marchandises ; le flux d'information pilote et trace les opérations (commandes, expéditions) ; le flux financier correspond aux règlements monétaires." },
      { id: 36, section: "Achats professionnels", question: "Définissez un achat professionnel et ses enjeux.", answer: "Correction : Acquisition de biens ou services répondant aux besoins de l'entreprise avec recherche du meilleur rapport qualité-coût-délai pour maximiser la marge opérationnelle." },
      { id: 41, section: "Approvisionnement", question: "Définissez le délai d’approvisionnement (Lead Time).", answer: "Correction : Temps écoulé entre l'émission du besoin d'achat (ou passation de commande) et la mise à disposition effective de la marchandise contrôlée dans l'entrepôt." },
      { id: 72, section: "Gestion des stocks", question: "Qu’est-ce qu’un stock de sécurité et pourquoi est-il indispensable ?", answer: "Correction : Niveau de stock tampon conservé en permanence pour absorber les aléas de la demande client (pics imprévus) ou les retards de livraison des fournisseurs." },
      { id: 75, section: "Gestion des stocks", question: "Expliquez le calcul du point de commande.", answer: "Correction : Niveau de stock qui déclenche l'ordre d'approvisionnement. Formule : Point de commande = (Consommation moyenne par jour × Délai de livraison en jours) + Stock de sécurité." },
      { id: 79, section: "Valorisation des stocks", question: "Expliquez la méthode FIFO (First In, First Out).", answer: "Correction : Règle de gestion consistant à consommer ou expédier en priorité les articles entrés les premiers en stock afin d'éviter la péremption ou l'obsolescence." },
      { id: 113, section: "Entrepôt", question: "Qu’est-ce que le picking dans un entrepôt ?", answer: "Correction : Opération de prélèvement unitaire des articles stockés sur les étagères ou palettes pour constituer le colis commandé par un client." },
      { id: 114, section: "Entrepôt", question: "Qu’est-ce que le cross-docking ?", answer: "Correction : Technique logistique consistant à transférer les marchandises des quais de déchargement directement vers les quais d'expédition sans mise en stock intermédiaire." },
      { id: 146, section: "Transport", question: "Définissez le transport multimodal et citez un exemple sénégalais.", answer: "Correction : Acheminement d'une marchandise empruntant au moins deux modes de transport successifs sous un contrat unique (ex: navire conteneurisé jusqu'au port de Dakar puis train ou camion vers le Mali)." },
      { id: 154, section: "Distribution", question: "Qu’est-ce que la logistique du dernier kilomètre ?", answer: "Correction : Dernier segment de la livraison entre la plateforme de distribution locale et le destinataire final, représentant souvent plus de 25% du coût global de transport." },
      { id: 206, section: "Calculs logistiques", question: "Une entreprise consomme 120 unités par jour pendant 5 jours. Calculez la consommation hebdomadaire.", answer: "Correction : 120 × 5 = 600 unités par semaine." },
      { id: 209, section: "Calculs logistiques", question: "Un entrepôt traite 900 colis en 6 heures. Calculez le débit horaire moyen.", answer: "Correction : Débit = 900 / 6 = 150 colis par heure." },
      { id: 211, section: "Calculs logistiques", question: "Un transport coûte 750 000 FCFA pour 150 tonnes. Calculez le coût par tonne.", answer: "Correction : 750 000 / 150 = 5 000 FCFA par tonne transportée." },
      { id: 212, section: "Qualité logistique", question: "Une livraison compte 96 colis dont 4 sont endommagés. Calculez le taux d’avarie.", answer: "Correction : Taux d'avarie = (4 / 96) × 100 = 4,17 %." },
      { id: 214, section: "Rotation des stocks", question: "Le stock moyen est de 2 000 unités et la consommation annuelle de 12 000 unités. Calculez le taux de rotation.", answer: "Correction : Taux de rotation = Consommation annuelle / Stock moyen = 12 000 / 2 000 = 6 rotations par an." },
      { id: 262, section: "Systèmes d'information", question: "À quoi sert un logiciel WMS (Warehouse Management System) ?", answer: "Correction : Système informatisé qui gère et optimise l'ensemble des opérations d'un entrepôt : réception, adressage des emplacements, préparation des commandes, inventaires et expéditions." },
      { id: 263, section: "Systèmes d'information", question: "À quoi sert un logiciel TMS (Transport Management System) ?", answer: "Correction : Logiciel dédié à la planification des tournées, à la sélection des transporteurs, au suivi géolocalisé des véhicules et au contrôle des factures de transport." },
      { id: 309, section: "Amélioration continue", question: "Présenter les 5 étapes de la démarche 5S en atelier ou entrepôt.", answer: "Correction : Seiri (Débarrasser), Seiton (Ranger), Seiso (Nettoyer), Seiketsu (Standardiser) et Shitsuke (Pérenniser/Rigueur)." }
